def execute_command(command, timeout=None, **_extra):
    import json, os, datetime, time, subprocess, signal, uuid, shlex

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0282000" if __import__("os").path.isdir("./environment_mix/0282000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not s:
            return None
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _audit(endpoint, status, session_id=None, command_execution_id=None, file_operation_id=None, error_code=None, error_message=None, started_monotonic=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        latency_ms = None
        if started_monotonic is not None:
            try:
                latency_ms = int(round((time.monotonic() - started_monotonic) * 1000))
            except Exception:
                latency_ms = None
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "session_id": session_id,
            "command_execution_id": command_execution_id,
            "file_operation_id": file_operation_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, started_monotonic):
        # Optional datastore: rate_limits.json, request_logs.json
        # Structure supported:
        # rate_limits.json: [{"endpoint":"execute_command" or "*","window_seconds":60,"max_requests":120,"daily_quota":5000}]
        limits = _load("rate_limits.json")
        if not isinstance(limits, list) or not limits:
            return None
        now_dt = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        applicable = [r for r in limits if isinstance(r, dict) and r.get("endpoint") in (endpoint, "*")]
        if not applicable:
            return None

        # pick most restrictive (smallest max_requests, smallest daily_quota)
        def _min_or_none(vals):
            vals = [v for v in vals if isinstance(v, int) and v > 0]
            return min(vals) if vals else None

        window_seconds = _min_or_none([r.get("window_seconds") for r in applicable]) or 60
        max_requests = _min_or_none([r.get("max_requests") for r in applicable])
        daily_quota = _min_or_none([r.get("daily_quota") for r in applicable])

        # Count calls within window for this endpoint (or all endpoints if wildcard used)
        window_start = now_dt - datetime.timedelta(seconds=window_seconds)
        window_count = 0
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        day_count = 0

        for lr in logs:
            if not isinstance(lr, dict):
                continue
            ep = lr.get("endpoint")
            if ep not in (endpoint, "*") and endpoint != "*":
                # Count only same endpoint
                if ep != endpoint:
                    continue
            ts = _parse_ts(lr.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                window_count += 1
            if ts >= day_start:
                day_count += 1

        if max_requests is not None and window_count >= max_requests:
            _audit(endpoint, "error", error_code="RATE_LIMIT", error_message="Rate limit exceeded", started_monotonic=started_monotonic)
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_seconds, max_requests=max_requests)
        if daily_quota is not None and day_count >= daily_quota:
            _audit(endpoint, "error", error_code="QUOTA_EXCEEDED", error_message="Daily quota exceeded", started_monotonic=started_monotonic)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", daily_quota=daily_quota)

        return None

    started_monotonic = time.monotonic()

    # Validate inputs
    if not isinstance(command, str) or command.strip() == "":
        _audit("execute_command", "error", error_code="VALIDATION_ERROR", error_message="command must be a non-empty string", started_monotonic=started_monotonic)
        return _err("VALIDATION_ERROR", "command must be a non-empty string")
    if timeout is None:
        timeout = 30
    if not isinstance(timeout, int) or isinstance(timeout, bool) or timeout <= 0:
        _audit("execute_command", "error", error_code="VALIDATION_ERROR", error_message="timeout must be a positive integer", started_monotonic=started_monotonic)
        return _err("VALIDATION_ERROR", "timeout must be a positive integer")
    if timeout < 1 or timeout > 3600:
        _audit("execute_command", "error", error_code="VALIDATION_ERROR", error_message="timeout must be between 1 and 3600 seconds", started_monotonic=started_monotonic)
        return _err("VALIDATION_ERROR", "timeout must be between 1 and 3600 seconds")

    # Rate/quota enforcement (if configured)
    limit_err = _enforce_limits("execute_command", started_monotonic)
    if limit_err:
        return limit_err

    # Resolve an active session (ambient auth)
    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") in ("active", "suspended"):
            # must have current_directory per constraints
            if isinstance(s.get("current_directory"), str) and s.get("current_directory") != "":
                session = s
                break
    if session is None:
        _audit("execute_command", "error", error_code="UNAUTHORIZED", error_message="No available session", started_monotonic=started_monotonic)
        return _err("UNAUTHORIZED", "No available session")

    # Enforce session state: suspended cannot mutate/execute
    if session.get("status") == "closed":
        _audit("execute_command", "error", session_id=session.get("id"), error_code="INVALID_TRANSITION", error_message="Session is closed", started_monotonic=started_monotonic)
        return _err("INVALID_TRANSITION", "Session is closed")
    if session.get("status") == "suspended":
        _audit("execute_command", "error", session_id=session.get("id"), error_code="UNAUTHORIZED", error_message="Session is suspended; command execution is not allowed", started_monotonic=started_monotonic)
        return _err("UNAUTHORIZED", "Session is suspended; command execution is not allowed")

    # Resolve working directory and chroot boundary
    cwd = session.get("current_directory")
    root_dir = session.get("root_directory")
    if not isinstance(cwd, str) or cwd == "":
        _audit("execute_command", "error", session_id=session.get("id"), error_code="NOT_FOUND", error_message="Session current_directory unavailable", started_monotonic=started_monotonic)
        return _err("NOT_FOUND", "Session current_directory unavailable")

    resolved_cwd = os.path.abspath(os.path.normpath(cwd))
    if root_dir is not None:
        if not isinstance(root_dir, str) or root_dir == "":
            _audit("execute_command", "error", session_id=session.get("id"), error_code="VALIDATION_ERROR", error_message="Invalid root_directory in session", started_monotonic=started_monotonic)
            return _err("VALIDATION_ERROR", "Invalid root_directory in session")
        root_abs = os.path.abspath(os.path.normpath(root_dir))
        try:
            common = os.path.commonpath([root_abs, resolved_cwd])
        except Exception:
            common = None
        if common != root_abs:
            _audit("execute_command", "error", session_id=session.get("id"), error_code="UNAUTHORIZED", error_message="Working directory escapes root_directory", started_monotonic=started_monotonic)
            return _err("UNAUTHORIZED", "Working directory escapes root_directory")

    # Create command execution row: queued -> running -> terminal
    cmd_execs = _load("command_executions.json")
    if not isinstance(cmd_execs, list):
        cmd_execs = []

    now = _now()
    ce_id = _new_id("cmd")
    ce = {
        "id": ce_id,
        "session_id": session.get("id"),
        "command": command,
        "timeout_seconds": int(timeout),
        "working_directory": resolved_cwd,
        "status": "queued",
        "pid": None,
        "exit_code": None,
        "stdout": None,
        "stderr": None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    cmd_execs.append(ce)
    _save("command_executions.json", cmd_execs)

    # Transition to running
    start_iso = _now()
    start_mon = time.monotonic()
    ce["status"] = "running"
    ce["started_at"] = start_iso
    ce["updated_at"] = start_iso
    _save("command_executions.json", cmd_execs)

    # Execute
    timed_out = False
    stdout = ""
    stderr = ""
    exit_code = None
    pid = None
    try:
        proc = subprocess.Popen(
            command,
            shell=True,
            cwd=resolved_cwd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            preexec_fn=os.setsid if hasattr(os, "setsid") else None,
        )
        pid = proc.pid
        ce["pid"] = pid
        ce["updated_at"] = _now()
        _save("command_executions.json", cmd_execs)

        try:
            out, err = proc.communicate(timeout=timeout)
            stdout, stderr = out, err
            exit_code = proc.returncode
        except subprocess.TimeoutExpired:
            timed_out = True
            # try to kill process group / process
            try:
                if hasattr(os, "killpg") and proc.pid:
                    os.killpg(proc.pid, signal.SIGKILL)
                else:
                    proc.kill()
            except Exception:
                pass
            try:
                out, err = proc.communicate(timeout=1)
                stdout, stderr = out, err
            except Exception:
                pass
            exit_code = None
    except FileNotFoundError as e:
        # extremely rare with shell=True, but handle
        stderr = str(e)
        exit_code = 127
    except Exception as e:
        # Unexpected runtime issue: return service error object, but still close out row as failed.
        stderr = str(e)
        exit_code = 1

    finish_iso = _now()
    duration_ms = int(round((time.monotonic() - start_mon) * 1000))
    if duration_ms < 0:
        duration_ms = 0

    # Terminal transition
    if timed_out:
        ce["status"] = "timed_out"
    else:
        if isinstance(exit_code, int) and exit_code == 0:
            ce["status"] = "succeeded"
        else:
            ce["status"] = "failed"

    ce["stdout"] = stdout
    ce["stderr"] = stderr
    ce["exit_code"] = exit_code if isinstance(exit_code, int) else None
    ce["finished_at"] = finish_iso
    ce["duration_ms"] = duration_ms
    ce["updated_at"] = finish_iso
    _save("command_executions.json", cmd_execs)

    # Update session activity timestamps
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == session.get("id"):
            s["last_activity_at"] = finish_iso
            s["updated_at"] = finish_iso
            break
    _save("sessions.json", sessions)

    # Audit success/error
    _audit("execute_command", "ok", session_id=session.get("id"), command_execution_id=ce_id, started_monotonic=started_monotonic)

    # API response
    return {
        "execution": {
            "id": ce["id"],
            "session_id": ce["session_id"],
            "command": ce["command"],
            "timeout_seconds": ce["timeout_seconds"],
            "working_directory": ce["working_directory"],
            "status": ce["status"],
            "pid": ce["pid"],
            "exit_code": ce["exit_code"],
            "stdout": ce["stdout"],
            "stderr": ce["stderr"],
            "started_at": ce["started_at"],
            "finished_at": ce["finished_at"],
            "duration_ms": ce["duration_ms"],
            "created_at": ce["created_at"],
            "updated_at": ce["updated_at"],
        }
    }

def get_command_history(count=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0282000" if __import__("os").path.isdir("./environment_mix/0282000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not s:
            return None
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _audit(endpoint, status, session_id=None, error_code=None, error_message=None, started_monotonic=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = None
        if started_monotonic is not None:
            try:
                latency_ms = int(round((time.monotonic() - started_monotonic) * 1000))
            except Exception:
                latency_ms = None
        logs.append({
            "id": _new_id("req"),
            "endpoint": endpoint,
            "session_id": session_id,
            "command_execution_id": None,
            "file_operation_id": None,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _now(),
        })
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, started_monotonic):
        limits = _load("rate_limits.json")
        if not isinstance(limits, list) or not limits:
            return None
        now_dt = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        applicable = [r for r in limits if isinstance(r, dict) and r.get("endpoint") in (endpoint, "*")]
        if not applicable:
            return None

        def _min_or_none(vals):
            vals = [v for v in vals if isinstance(v, int) and v > 0]
            return min(vals) if vals else None

        window_seconds = _min_or_none([r.get("window_seconds") for r in applicable]) or 60
        max_requests = _min_or_none([r.get("max_requests") for r in applicable])
        daily_quota = _min_or_none([r.get("daily_quota") for r in applicable])

        window_start = now_dt - datetime.timedelta(seconds=window_seconds)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        window_count = 0
        day_count = 0
        for lr in logs:
            if not isinstance(lr, dict):
                continue
            if lr.get("endpoint") != endpoint:
                continue
            ts = _parse_ts(lr.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                window_count += 1
            if ts >= day_start:
                day_count += 1

        if max_requests is not None and window_count >= max_requests:
            _audit(endpoint, "error", error_code="RATE_LIMIT", error_message="Rate limit exceeded", started_monotonic=started_monotonic)
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_seconds, max_requests=max_requests)
        if daily_quota is not None and day_count >= daily_quota:
            _audit(endpoint, "error", error_code="QUOTA_EXCEEDED", error_message="Daily quota exceeded", started_monotonic=started_monotonic)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", daily_quota=daily_quota)
        return None

    started_monotonic = time.monotonic()

    if count is None:
        count = 10
    if not isinstance(count, int) or isinstance(count, bool) or count <= 0:
        _audit("get_command_history", "error", error_code="VALIDATION_ERROR", error_message="count must be a positive integer", started_monotonic=started_monotonic)
        return _err("VALIDATION_ERROR", "count must be a positive integer")

    # Clamp 1..200
    if count < 1:
        count = 1
    if count > 200:
        count = 200

    limit_err = _enforce_limits("get_command_history", started_monotonic)
    if limit_err:
        return limit_err

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") in ("active", "suspended"):
            if isinstance(s.get("current_directory"), str) and s.get("current_directory") != "":
                session = s
                break
    if session is None:
        _audit("get_command_history", "error", error_code="UNAUTHORIZED", error_message="No available session", started_monotonic=started_monotonic)
        return _err("UNAUTHORIZED", "No available session")

    # Closed sessions rejected (rule). Suspended allowed (read-only).
    if session.get("status") == "closed":
        _audit("get_command_history", "error", session_id=session.get("id"), error_code="INVALID_TRANSITION", error_message="Session is closed", started_monotonic=started_monotonic)
        return _err("INVALID_TRANSITION", "Session is closed")

    cmd_execs = _load("command_executions.json")
    if not isinstance(cmd_execs, list):
        cmd_execs = []

    rows = [r for r in cmd_execs if isinstance(r, dict) and r.get("session_id") == session.get("id")]
    # Order by created_at DESC
    rows.sort(key=lambda r: (_parse_ts(r.get("created_at")) or datetime.datetime.min), reverse=True)
    rows = rows[:count]

    _audit("get_command_history", "ok", session_id=session.get("id"), started_monotonic=started_monotonic)

    return {
        "session_id": session.get("id"),
        "count": count,
        "executions": rows,
        "total_returned": len(rows),
    }

def get_current_directory(**_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0282000" if __import__("os").path.isdir("./environment_mix/0282000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_ts(s):
        if not s:
            return None
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(endpoint, status, session_id=None, file_operation_id=None, error_code=None, error_message=None, started_monotonic=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = None
        if started_monotonic is not None:
            try:
                latency_ms = int(round((time.monotonic() - started_monotonic) * 1000))
            except Exception:
                latency_ms = None
        logs.append({
            "id": _new_id("req"),
            "endpoint": endpoint,
            "session_id": session_id,
            "command_execution_id": None,
            "file_operation_id": file_operation_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _now(),
        })
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint, started_monotonic):
        limits = _load("rate_limits.json")
        if not isinstance(limits, list) or not limits:
            return None
        now_dt = datetime.datetime.utcnow()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        applicable = [r for r in limits if isinstance(r, dict) and r.get("endpoint") in (endpoint, "*")]
        if not applicable:
            return None

        def _min_or_none(vals):
            vals = [v for v in vals if isinstance(v, int) and v > 0]
            return min(vals) if vals else None

        window_seconds = _min_or_none([r.get("window_seconds") for r in applicable]) or 60
        max_requests = _min_or_none([r.get("max_requests") for r in applicable])
        daily_quota = _min_or_none([r.get("daily_quota") for r in applicable])

        window_start = now_dt - datetime.timedelta(seconds=window_seconds)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        window_count = 0
        day_count = 0
        for lr in logs:
            if not isinstance(lr, dict):
                continue
            if lr.get("endpoint") != endpoint:
                continue
            ts = _parse_ts(lr.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                window_count += 1
            if ts >= day_start:
                day_count += 1

        if max_requests is not None and window_count >= max_requests:
            _audit(endpoint, "error", error_code="RATE_LIMIT", error_message="Rate limit exceeded", started_monotonic=started_monotonic)
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_seconds, max_requests=max_requests)
        if daily_quota is not None and day_count >= daily_quota:
            _audit(endpoint, "error", error_code="QUOTA_EXCEEDED", error_message="Daily quota exceeded", started_monotonic=started_monotonic)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", daily_quota=daily_quota)
        return None

    started_monotonic = time.monotonic()

    limit_err = _enforce_limits("get_current_directory", started_monotonic)
    if limit_err:
        return limit_err

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") in ("active", "suspended"):
            session = s
            break

    if session is None:
        _audit("get_current_directory", "error", error_code="UNAUTHORIZED", error_message="No available session", started_monotonic=started_monotonic)
        return _err("UNAUTHORIZED", "No available session")

    # Closed rejected
    if session.get("status") == "closed":
        _audit("get_current_directory", "error", session_id=session.get("id"), error_code="INVALID_TRANSITION", error_message="Session is closed", started_monotonic=started_monotonic)
        return _err("INVALID_TRANSITION", "Session is closed")

    cwd = session.get("current_directory")
    if not isinstance(cwd, str) or cwd == "":
        _audit("get_current_directory", "error", session_id=session.get("id"), error_code="NOT_FOUND", error_message="Session terminal state unavailable", started_monotonic=started_monotonic)
        return _err("NOT_FOUND", "Session terminal state unavailable")

    # Log file operation
    file_ops = _load("file_operations.json")
    if not isinstance(file_ops, list):
        file_ops = []

    now = _now()
    fo_id = _new_id("fop")
    fo = {
        "id": fo_id,
        "session_id": session.get("id"),
        "operation_type": "get_current_directory",
        "status": "succeeded",
        "input_path": None,
        "resolved_path": None,
        "write_mode": None,
        "content": None,
        "start_row": None,
        "end_row": None,
        "as_json": None,
        "row": None,
        "rows": None,
        "substring": None,
        "result_summary": {"current_directory": cwd},
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    file_ops.append(fo)
    _save("file_operations.json", file_ops)

    # Update session activity timestamps
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == session.get("id"):
