def change_directory(path, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0282000" if __import__("os").path.isdir("./environment_mix/0282000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.monotonic()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix, existing_ids):
        # Match existing db's style but uniqueness is what matters
        while True:
            cand = f"tc_{prefix}_{now_dt.strftime('%y%m%d%H%M%S')}{secrets.token_hex(8)}"
            if cand not in existing_ids:
                return cand

    def _pick_session(sessions_rows):
        cands = [s for s in sessions_rows if isinstance(s, dict) and isinstance(s.get("id"), str) and s.get("status") in ("active", "suspended", "closed")]
        if not cands:
            return None
        cands.sort(key=lambda s: (s.get("last_activity_at") or "", s.get("updated_at") or "", s.get("created_at") or "", s.get("id")), reverse=True)
        # Prefer active, then suspended, then closed
        for st in ("active", "suspended", "closed"):
            for s in cands:
                if s.get("status") == st:
                    return s
        return cands[0]

    def _resolve_path(session, in_path):
        if not isinstance(in_path, str) or not in_path.strip():
            return None, _err("VALIDATION_ERROR", "path must be a non-empty string.", rule="path_non_empty")
        cwd = session.get("current_directory")
        if not isinstance(cwd, str) or not cwd:
            return None, _err("CONFLICT", "Session current_directory is not set.", rule="session_current_directory")

        base = cwd if os.path.isabs(cwd) else os.path.abspath(cwd)
        joined = in_path if os.path.isabs(in_path) else os.path.join(base, in_path)
        resolved = os.path.abspath(os.path.normpath(joined))

        root = session.get("root_directory")
        if root is not None:
            if not isinstance(root, str) or not root:
                return resolved, _err("VALIDATION_ERROR", "Session root_directory is invalid.", rule="root_directory_valid")
            root_abs = os.path.abspath(os.path.normpath(root))
            try:
                common = os.path.commonpath([root_abs, resolved])
            except ValueError:
                common = None
            if common != root_abs:
                return resolved, _err(
                    "VALIDATION_ERROR",
                    f"Resolved path escapes root_directory ({root_abs}).",
                    rule="root_directory_boundary",
                    root_directory=root_abs,
                    resolved_path=resolved,
                )
        return resolved, None

    sessions = _load("sessions.json")
    file_ops = _load("file_operations.json")
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(file_ops, list):
        file_ops = []

    sess = _pick_session(sessions)
    if not sess:
        return _err("UNAUTHORIZED", "No session available to change directory.")

    sid = sess.get("id")
    st = sess.get("status")
    if st == "closed":
        # must reject mutating ops when closed
        return _err("INVALID_TRANSITION", "Session is closed; operation rejected.", session_id=sid)
    if st == "suspended":
        return _err("INVALID_TRANSITION", "Session is suspended; mutating operations are not allowed.", session_id=sid)

    resolved_path, perr = _resolve_path(sess, path)

    # create file op row (even on failures like root boundary)
    existing_ids = {r.get("id") for r in file_ops if isinstance(r, dict)}
    op = {
        "id": _gen_id("fop", existing_ids),
        "session_id": sid,
        "operation_type": "change_directory",
        "status": "pending",
        "input_path": path,
        "resolved_path": resolved_path,
        "write_mode": None,
        "content": None,
        "start_row": None,
        "end_row": None,
        "as_json": None,
        "row": None,
        "rows": None,
        "substring": None,
        "result_summary": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    if perr:
        op["status"] = "failed"
        op["error_message"] = perr["error"]["message"]
        op["updated_at"] = now
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        # also update session activity timestamps
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["last_activity_at"] = now
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)
        perr["error"]["operation"] = op
        return perr

    # verify directory exists and is directory
    try:
        exists = os.path.exists(resolved_path)
    except OSError:
        exists = False
    if not exists:
        op["status"] = "failed"
        op["error_message"] = "Directory does not exist."
        op["updated_at"] = now
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["last_activity_at"] = now
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)
        return _err("NOT_FOUND", "Directory does not exist.", resolved_path=resolved_path, operation=op)

    try:
        is_dir = os.path.isdir(resolved_path)
    except OSError:
        is_dir = False
    if not is_dir:
        op["status"] = "failed"
        op["error_message"] = "Path exists but is not a directory."
        op["updated_at"] = now
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["last_activity_at"] = now
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)
        return _err("CONFLICT", "Path exists but is not a directory.", resolved_path=resolved_path, operation=op)

    # apply session mutation
    updated = False
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sid:
            s["current_directory"] = resolved_path
            s["last_activity_at"] = now
            s["updated_at"] = now
            updated = True
            sess = s
            break
    if not updated:
        op["status"] = "failed"
        op["error_message"] = "Session not found."
        op["updated_at"] = now
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        return _err("NOT_FOUND", "Session not found.", session_id=sid, operation=op)

    op["status"] = "succeeded"
    op["result_summary"] = {"new_cwd": resolved_path}
    op["updated_at"] = now
    file_ops.append(op)

    _save("sessions.json", sessions)
    _save("file_operations.json", file_ops)

    latency_ms = int((time.monotonic() - t0) * 1000)
    return {"session": dict(sess), "operation": op, "latency_ms": latency_ms}

def list_directory(path=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0282000" if __import__("os").path.isdir("./environment_mix/0282000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.monotonic()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix, existing_ids):
        while True:
            cand = f"tc_{prefix}_{now_dt.strftime('%y%m%d%H%M%S')}{secrets.token_hex(8)}"
            if cand not in existing_ids:
                return cand

    def _pick_session(sessions_rows):
        cands = [s for s in sessions_rows if isinstance(s, dict) and isinstance(s.get("id"), str) and s.get("status") in ("active", "suspended", "closed")]
        if not cands:
            return None
        cands.sort(key=lambda s: (s.get("last_activity_at") or "", s.get("updated_at") or "", s.get("created_at") or "", s.get("id")), reverse=True)
        for st in ("active", "suspended", "closed"):
            for s in cands:
                if s.get("status") == st:
                    return s
        return cands[0]

    def _resolve_path(session, in_path):
        cwd = session.get("current_directory")
        if not isinstance(cwd, str) or not cwd:
            return None, _err("CONFLICT", "Session current_directory is not set.", rule="session_current_directory")
        if in_path is not None and not isinstance(in_path, str):
            return None, _err("VALIDATION_ERROR", "path must be a string or null.", rule="path_type")

        use_path = cwd if in_path is None else in_path
        if isinstance(use_path, str) and use_path == "":
            return None, _err("VALIDATION_ERROR", "path must not be empty.", rule="path_non_empty")

        base = cwd if os.path.isabs(cwd) else os.path.abspath(cwd)
        joined = use_path if os.path.isabs(use_path) else os.path.join(base, use_path)
        resolved = os.path.abspath(os.path.normpath(joined))

        root = session.get("root_directory")
        if root is not None:
            if not isinstance(root, str) or not root:
                return resolved, _err("VALIDATION_ERROR", "Session root_directory is invalid.", rule="root_directory_valid")
            root_abs = os.path.abspath(os.path.normpath(root))
            try:
                common = os.path.commonpath([root_abs, resolved])
            except ValueError:
                common = None
            if common != root_abs:
                return resolved, _err(
                    "VALIDATION_ERROR",
                    f"Resolved path escapes root_directory ({root_abs}).",
                    rule="root_directory_boundary",
                    root_directory=root_abs,
                    resolved_path=resolved,
                )
        return resolved, None

    sessions = _load("sessions.json")
    file_ops = _load("file_operations.json")
    cache = _load("fs_entries_cache.json")
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(file_ops, list):
        file_ops = []
    if not isinstance(cache, list):
        cache = []

    sess = _pick_session(sessions)
    if not sess:
        return _err("UNAUTHORIZED", "No session available to list directory.")
    sid = sess.get("id")
    if sess.get("status") == "closed":
        return _err("INVALID_TRANSITION", "Session is closed; operation rejected.", session_id=sid)

    resolved_path, perr = _resolve_path(sess, path)

    # log op row even when failing root boundary
    existing_ids = {r.get("id") for r in file_ops if isinstance(r, dict)}
    op = {
        "id": _gen_id("fop", existing_ids),
        "session_id": sid,
        "operation_type": "list_directory",
        "status": "pending",
        "input_path": path,
        "resolved_path": resolved_path,
        "write_mode": None,
        "content": None,
        "start_row": None,
        "end_row": None,
        "as_json": None,
        "row": None,
        "rows": None,
        "substring": None,
        "result_summary": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    if perr:
        op["status"] = "failed"
        op["error_message"] = perr["error"]["message"]
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["last_activity_at"] = now
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)
        perr["error"]["operation"] = op
        return perr

    # cache lookup (valid and not expired)
    def _parse_dt(s):
        if not isinstance(s, str) or not s.endswith("Z"):
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1])
        except ValueError:
            return None

    cached_row = None
    for r in cache:
        if isinstance(r, dict) and r.get("session_id") == sid and r.get("path") == resolved_path and r.get("entry_type") == "directory_listing":
            cached_row = r
            break
    if cached_row and cached_row.get("status") == "valid":
        exp = _parse_dt(cached_row.get("expires_at"))
        if exp is not None and exp < now_dt:
            # transition valid -> stale
            cached_row["status"] = "stale"
            cached_row["updated_at"] = now
            _save("fs_entries_cache.json", cache)
            cached_row = None

    # perform listing (must not error if directory missing? vendor says NOT_FOUND; so return error but include op)
    try:
        exists = os.path.exists(resolved_path)
    except OSError:
        exists = False
    if not exists:
        op["status"] = "failed"
        op["error_message"] = "Directory does not exist."
        op["updated_at"] = now
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["last_activity_at"] = now
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)
        return _err("NOT_FOUND", "Directory does not exist.", resolved_path=resolved_path, operation=op)

    try:
        is_dir = os.path.isdir(resolved_path)
    except OSError:
        is_dir = False
    if not is_dir:
        op["status"] = "failed"
        op["error_message"] = "Resolved path is not a directory."
        op["updated_at"] = now
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["last_activity_at"] = now
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)
        return _err("CONFLICT", "Resolved path is not a directory.", resolved_path=resolved_path, operation=op)

    # Use cached payload if available and valid
    entries_payload = None
    cache_hit = False
    if cached_row and cached_row.get("status") == "valid" and isinstance(cached_row.get("payload"), list):
        entries_payload = cached_row["payload"]
        cache_hit = True
    else:
        # build listing
        entries = []
        try:
            names = os.listdir(resolved_path)
        except OSError as e:
            op["status"] = "failed"
            op["error_message"] = str(e)
            op["updated_at"] = now
            file_ops.append(op)
            _save("file_operations.json", file_ops)
            for s in sessions:
                if isinstance(s, dict) and s.get("id") == sid:
                    s["last_activity_at"] = now
                    s["updated_at"] = now
                    break
            _save("sessions.json", sessions)
            return _err("CONFLICT", "Unable to list directory.", resolved_path=resolved_path, operation=op)

        for nm in sorted(names):
            full = os.path.join(resolved_path, nm)
            try:
                st = os.stat(full)
                is_d = os.path.isdir(full)
                entry = {
                    "name": nm,
                    "path": full,
                    "type": "directory" if is_d else "file",
                    "size": int(getattr(st, "st_size", 0)),
                    "mtime": datetime.datetime.utcfromtimestamp(getattr(st, "st_mtime", 0)).replace(microsecond=0).isoformat() + "Z",
                }
            except OSError:
                entry = {"name": nm, "path": full, "type": "unknown"}
            entries.append(entry)
        entries_payload = entries

        # upsert cache entry for (sid,path,entry_type)
        if cached_row is None:
            existing_ids = {r.get("id") for r in cache if isinstance(r, dict)}
            new_cache = {
                "id": _gen_id("fsc", existing_ids),
                "session_id": sid,
                "path": resolved_path,
                "entry_type": "directory_listing",
                "status": "valid",
                "payload": entries_payload,
                "etag": None,
                "expires_at": (now_dt + datetime.timedelta(seconds=30)).replace(microsecond=0).isoformat() + "Z",
                "created_at": now,
                "updated_at": now,
            }
            cache.append(new_cache)
        else:
            # stale/invalid -> valid
            cached_row["status"] = "valid"
            cached_row["payload"] = entries_payload
            cached_row["expires_at"] = (now_dt + datetime.timedelta(seconds=30)).replace(microsecond=0).isoformat() + "Z"
            cached_row["updated_at"] = now
        _save("fs_entries_cache.json", cache)

    op["status"] = "succeeded"
    op["result_summary"] = {"entries_count": len(entries_payload), "path": resolved_path, "cache_hit": cache_hit}
    op["updated_at"] = now
    file_ops.append(op)
    _save("file_operations.json", file_ops)

    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sid:
            s["last_activity_at"] = now
            s["updated_at"] = now
            break
    _save("sessions.json", sessions)

    latency_ms = int((time.monotonic() - t0) * 1000)
    return {"path": resolved_path, "entries": entries_payload, "operation": op, "latency_ms": latency_ms}

