        parent_is_dir = False
    if not parent_is_dir:
        op["status"] = "failed"
        op["error_message"] = "Parent path exists but is not a directory."
        op["updated_at"] = now
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["last_activity_at"] = now
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)
        return _err("CONFLICT", "Parent path exists but is not a directory.", resolved_path=resolved_path, operation=op)

    try:
        if os.path.exists(resolved_path) and os.path.isdir(resolved_path):
            op["status"] = "failed"
            op["error_message"] = "Path refers to a directory."
            op["updated_at"] = now
            file_ops.append(op)
            _save("file_operations.json", file_ops)
            for s in sessions:
                if isinstance(s, dict) and s.get("id") == sid:
                    s["last_activity_at"] = now
                    s["updated_at"] = now
                    break
            _save("sessions.json", sessions)
            return _err("CONFLICT", "Path refers to a directory.", resolved_path=resolved_path, operation=op)
    except OSError:
        pass

    bytes_written = 0
    try:
        if mode == "overwrite":
            with open(resolved_path, "w", encoding="utf-8") as f:
                bytes_written = f.write(content)
        else:
            with open(resolved_path, "a", encoding="utf-8") as f:
                bytes_written = f.write(content)
    except OSError as e:
        op["status"] = "failed"
        op["error_message"] = str(e)
        op["updated_at"] = now
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["last_activity_at"] = now
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)
        return _err("CONFLICT", "Write could not be applied.", resolved_path=resolved_path, operation=op)

    _invalidate_cache_for_path(resolved_path)

    op["status"] = "succeeded"
    op["result_summary"] = {"bytes_written": int(bytes_written), "mode": mode, "path": resolved_path}
    op["updated_at"] = now
    file_ops.append(op)
    _save("file_operations.json", file_ops)

    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sid:
            s["last_activity_at"] = now
            s["updated_at"] = now
            break
    _save("sessions.json", sessions)

    latency_ms = int((time.monotonic() - t0) * 1000)
    return {"operation": op, "latency_ms": latency_ms}

def read_file(path, start_row=None, end_row=None, as_json=False, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0282000" if __import__("os").path.isdir("./environment_mix/0282000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.monotonic()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix, existing_ids):
        while True:
            cand = f"tc_{prefix}_{now_dt.strftime('%y%m%d%H%M%S')}{secrets.token_hex(8)}"
            if cand not in existing_ids:
                return cand

    def _pick_session(sessions_rows):
        cands = [s for s in sessions_rows if isinstance(s, dict) and isinstance(s.get("id"), str) and s.get("status") in ("active", "suspended", "closed")]
        if not cands:
            return None
        cands.sort(key=lambda s: (s.get("last_activity_at") or "", s.get("updated_at") or "", s.get("created_at") or "", s.get("id")), reverse=True)
        for st in ("active", "suspended", "closed"):
            for s in cands:
                if s.get("status") == st:
                    return s
        return cands[0]

    def _resolve_path(session, in_path):
        if not isinstance(in_path, str) or not in_path.strip():
            return None, _err("VALIDATION_ERROR", "path must be a non-empty string.", rule="path_non_empty")
        cwd = session.get("current_directory")
        if not isinstance(cwd, str) or not cwd:
            return None, _err("CONFLICT", "Session current_directory is not set.", rule="session_current_directory")
        base = cwd if os.path.isabs(cwd) else os.path.abspath(cwd)
        joined = in_path if os.path.isabs(in_path) else os.path.join(base, in_path)
        resolved = os.path.abspath(os.path.normpath(joined))

        root = session.get("root_directory")
        if root is not None:
            if not isinstance(root, str) or not root:
                return resolved, _err("VALIDATION_ERROR", "Session root_directory is invalid.", rule="root_directory_valid")
            root_abs = os.path.abspath(os.path.normpath(root))
            try:
                common = os.path.commonpath([root_abs, resolved])
            except ValueError:
                common = None
            if common != root_abs:
                return resolved, _err(
                    "VALIDATION_ERROR",
                    f"Resolved path escapes root_directory ({root_abs}).",
                    rule="root_directory_boundary",
                    root_directory=root_abs,
                    resolved_path=resolved,
                )
        return resolved, None

    # validate row params
    if start_row is not None and (not isinstance(start_row, int) or start_row < 0):
        return _err("VALIDATION_ERROR", "start_row must be null or an integer >= 0.", rule="start_row_range")
    if end_row is not None and (not isinstance(end_row, int) or end_row < 0):
        return _err("VALIDATION_ERROR", "end_row must be null or an integer >= 0.", rule="end_row_range")
    if start_row is not None and end_row is not None and end_row < start_row:
        return _err("VALIDATION_ERROR", f"Invalid range: end_row ({end_row}) must be >= start_row ({start_row}).", rule="row_range")

    if as_json is not None and not isinstance(as_json, bool):
        return _err("VALIDATION_ERROR", "as_json must be a boolean.", rule="as_json_type")

    sessions = _load("sessions.json")
    file_ops = _load("file_operations.json")
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(file_ops, list):
        file_ops = []

    sess = _pick_session(sessions)
    if not sess:
        return _err("UNAUTHORIZED", "No session available to read file.")
    sid = sess.get("id")
    if sess.get("status") == "closed":
        return _err("INVALID_TRANSITION", "Session is closed; operation rejected.", session_id=sid)
    # suspended is allowed (read-only)

    resolved_path, perr = _resolve_path(sess, path)

    existing_ids = {r.get("id") for r in file_ops if isinstance(r, dict)}
    op = {
        "id": _gen_id("fop", existing_ids),
        "session_id": sid,
        "operation_type": "read_file",
        "status": "pending",
        "input_path": path,
        "resolved_path": resolved_path,
        "write_mode": None,
        "content": None,
        "start_row": start_row,
        "end_row": end_row,
        "as_json": bool(as_json),
        "row": None,
        "rows": None,
        "substring": None,
        "result_summary": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    if perr:
        op["status"] = "failed"
        op["error_message"] = perr["error"]["message"]
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["last_activity_at"] = now
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)
        perr["error"]["operation"] = op
        return perr

    try:
        exists = os.path.exists(resolved_path)
    except OSError:
        exists = False
    if not exists:
        op["status"] = "failed"
        op["error_message"] = "File does not exist."
        op["updated_at"] = now
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["last_activity_at"] = now
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)
        return _err("NOT_FOUND", "File does not exist.", resolved_path=resolved_path, operation=op)

    try:
        if os.path.isdir(resolved_path):
            op["status"] = "failed"
            op["error_message"] = "Path is a directory."
            op["updated_at"] = now
            file_ops.append(op)
            _save("file_operations.json", file_ops)
            for s in sessions:
                if isinstance(s, dict) and s.get("id") == sid:
                    s["last_activity_at"] = now
                    s["updated_at"] = now
                    break
            _save("sessions.json", sessions)
            return _err("CONFLICT", "Path is a directory.", resolved_path=resolved_path, operation=op)
    except OSError:
        pass

    # Read file
    try:
        with open(resolved_path, "r", encoding="utf-8") as f:
            text = f.read()
    except OSError as e:
        op["status"] = "failed"
        op["error_message"] = str(e)
        op["updated_at"] = now
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["last_activity_at"] = now
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)
        return _err("CONFLICT", "Unable to read file.", resolved_path=resolved_path, operation=op)

    lines = text.splitlines()
    total_lines = len(lines)

    if start_row is not None or end_row is not None:
        sr = 0 if start_row is None else start_row
        er = (total_lines - 1) if end_row is None else end_row
        if sr >= total_lines:
            selected_lines = []
        else:
            selected_lines = lines[sr : min(er + 1, total_lines)]
        selected_text = "\n".join(selected_lines)
        returned_lines = len(selected_lines)
        range_info = {"start_row": sr, "end_row": er}
    else:
        selected_text = text
        returned_lines = total_lines
        range_info = None

    parsed = None
    if as_json:
        try:
            parsed = json.loads(selected_text)
        except Exception:
            op["status"] = "failed"
            op["error_message"] = "JSON parsing failed."
            op["updated_at"] = now
            op["result_summary"] = {"path": resolved_path, "bytes_read": len(selected_text.encode("utf-8")), "lines_read": returned_lines, "range": range_info}
            file_ops.append(op)
            _save("file_operations.json", file_ops)
            for s in sessions:
                if isinstance(s, dict) and s.get("id") == sid:
                    s["last_activity_at"] = now
                    s["updated_at"] = now
                    break
            _save("sessions.json", sessions)
            return _err("VALIDATION_ERROR", "JSON parsing failed.", resolved_path=resolved_path, operation=op)

    op["status"] = "succeeded"
    op["result_summary"] = {"path": resolved_path, "bytes_read": len(selected_text.encode("utf-8")), "lines_read": returned_lines, "total_lines": total_lines, "range": range_info, "as_json": bool(as_json)}
    op["updated_at"] = now
    file_ops.append(op)
    _save("file_operations.json", file_ops)

    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sid:
            s["last_activity_at"] = now
            s["updated_at"] = now
            break
    _save("sessions.json", sessions)

    latency_ms = int((time.monotonic() - t0) * 1000)
    if as_json:
        return {"path": resolved_path, "json": parsed, "operation": op, "latency_ms": latency_ms}
    return {"path": resolved_path, "content": selected_text, "operation": op, "latency_ms": latency_ms}

def insert_file_content(path, content, row=None, rows=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0282000" if __import__("os").path.isdir("./environment_mix/0282000") else "/app/database")
    def _load(n):
