    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.monotonic()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix, existing_ids):
        while True:
            cand = f"tc_{prefix}_{now_dt.strftime('%y%m%d%H%M%S')}{secrets.token_hex(8)}"
            if cand not in existing_ids:
                return cand

    def _pick_session(sessions_rows):
        cands = [s for s in sessions_rows if isinstance(s, dict) and isinstance(s.get("id"), str) and s.get("status") in ("active", "suspended", "closed")]
        if not cands:
            return None
        cands.sort(key=lambda s: (s.get("last_activity_at") or "", s.get("updated_at") or "", s.get("created_at") or "", s.get("id")), reverse=True)
        for st in ("active", "suspended", "closed"):
            for s in cands:
                if s.get("status") == st:
                    return s
        return cands[0]

    def _resolve_path(session, in_path):
        if not isinstance(in_path, str) or not in_path.strip():
            return None, _err("VALIDATION_ERROR", "path must be a non-empty string.", rule="path_non_empty")
        cwd = session.get("current_directory")
        if not isinstance(cwd, str) or not cwd:
            return None, _err("CONFLICT", "Session current_directory is not set.", rule="session_current_directory")
        base = cwd if os.path.isabs(cwd) else os.path.abspath(cwd)
        joined = in_path if os.path.isabs(in_path) else os.path.join(base, in_path)
        resolved = os.path.abspath(os.path.normpath(joined))

        root = session.get("root_directory")
        if root is not None:
            if not isinstance(root, str) or not root:
                return resolved, _err("VALIDATION_ERROR", "Session root_directory is invalid.", rule="root_directory_valid")
            root_abs = os.path.abspath(os.path.normpath(root))
            try:
                common = os.path.commonpath([root_abs, resolved])
            except ValueError:
                common = None
            if common != root_abs:
                return resolved, _err(
                    "VALIDATION_ERROR",
                    f"Resolved path escapes root_directory ({root_abs}).",
                    rule="root_directory_boundary",
                    root_directory=root_abs,
                    resolved_path=resolved,
                )
        return resolved, None

    if not isinstance(content, str) or content == "":
        return _err("VALIDATION_ERROR", "content must be a non-empty string.", rule="content_non_empty")
    if (row is not None) and (rows is not None):
        return _err("VALIDATION_ERROR", "Provide exactly one of row or rows.", rule="row_xor_rows")
    if row is None and rows is None:
        return _err("VALIDATION_ERROR", "Either row or rows must be provided.", rule="row_or_rows_required")
    if row is not None and (not isinstance(row, int) or row < 0):
        return _err("VALIDATION_ERROR", "row must be an integer >= 0.", rule="row_range")
    if rows is not None:
        if not isinstance(rows, list):
            return _err("VALIDATION_ERROR", "rows must be an array of integers.", rule="rows_type")
        bad = [x for x in rows if not isinstance(x, int) or x < 0]
        if bad:
            return _err("VALIDATION_ERROR", "rows must be unique non-negative integers.", rule="rows_range")
        if len(set(rows)) != len(rows):
            # include duplicates detail similar to existing DB patterns
            dups = []
            seen = set()
            for x in rows:
                if x in seen and x not in dups:
                    dups.append(x)
                seen.add(x)
            return _err("VALIDATION_ERROR", f"rows must be unique non-negative integers; duplicates found: {', '.join(str(x) for x in dups) if dups else ''}.", rule="rows_unique", duplicates=dups)

    sessions = _load("sessions.json")
    file_ops = _load("file_operations.json")
    cache = _load("fs_entries_cache.json")
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(file_ops, list):
        file_ops = []
    if not isinstance(cache, list):
        cache = []

    sess = _pick_session(sessions)
    if not sess:
        return _err("UNAUTHORIZED", "No session available to insert file content.")
    sid = sess.get("id")
    st = sess.get("status")
    if st == "closed":
        return _err("INVALID_TRANSITION", "Session is closed; operation rejected.", session_id=sid)
    if st == "suspended":
        return _err("INVALID_TRANSITION", "Session is suspended; mutating operations are not allowed.", session_id=sid)

    resolved_path, perr = _resolve_path(sess, path)

    existing_ids = {r.get("id") for r in file_ops if isinstance(r, dict)}
    op = {
        "id": _gen_id("fop", existing_ids),
        "session_id": sid,
        "operation_type": "insert_file_content",
        "status": "pending",
        "input_path": path,
        "resolved_path": resolved_path,
        "write_mode": None,
        "content": content,
        "start_row": None,
        "end_row": None,
        "as_json": None,
        "row": row,
        "rows": rows,
        "substring": None,
        "result_summary": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    def _invalidate_cache(file_path):
        parent = os.path.dirname(file_path)
        changed = False
        for r in cache:
            if not isinstance(r, dict):
                continue
            if r.get("session_id") != sid:
                continue
            if r.get("path") in (file_path, parent):
                if r.get("status") != "invalid":
                    r["status"] = "invalid"
                    r["updated_at"] = now
                    changed = True
        if changed:
            _save("fs_entries_cache.json", cache)

    if perr:
        op["status"] = "failed"
        op["error_message"] = perr["error"]["message"]
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["last_activity_at"] = now
                s["updated_at"] = now
                break
        _save("sessions.json", sessions)
        perr["error"]["operation"] = op
        return perr

    try:
        exists = os.path.exists(resolved_path)
    except OSError:
        exists = False
    if not exists:
        op["status"] = "failed"
        op["error_message"] = "File does not exist."
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        return _err("NOT_FOUND", "File does not exist.", resolved_path=resolved_path, operation=op)
    try:
        if os.path.isdir(resolved_path):
            op["status"] = "failed"
            op["error_message"] = "Path is a directory."
            file_ops.append(op)
            _save("file_operations.json", file_ops)
            return _err("CONFLICT", "Path is a directory.", resolved_path=resolved_path, operation=op)
    except OSError:
        pass

    # apply insert(s)
    try:
        with open(resolved_path, "r", encoding="utf-8") as f:
            lines = f.read().splitlines(True)  # keepends
    except OSError as e:
        op["status"] = "failed"
        op["error_message"] = str(e)
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        return _err("CONFLICT", "Unable to read file.", resolved_path=resolved_path, operation=op)

    insert_indices = [row] if row is not None else sorted(set(rows))
    # insert at each row; applying from smallest to largest requires offset tracking
    new_lines = list(lines)
    inserted = 0
    for idx in insert_indices:
        pos = min(idx + inserted, len(new_lines))
        # Insert as a whole line; keep newline behavior: if content already endswith newline keep; else add newline
        ins = content
        if not ins.endswith("\n"):
            ins = ins + "\n"
        new_lines.insert(pos, ins)
        inserted += 1

    try:
        with open(resolved_path, "w", encoding="utf-8") as f:
            f.write("".join(new_lines))
    except OSError as e:
        op["status"] = "failed"
        op["error_message"] = str(e)
        file_ops.append(op)
        _save("file_operations.json", file_ops)
        return _err("CONFLICT", "Write could not be applied.", resolved_path=resolved_path, operation=op)

    _invalidate_cache(resolved_path)

    op["status"] = "succeeded"
    op["result_summary"] = {"rows_inserted": inserted, "path": resolved_path}
    op["updated_at"] = now
    file_ops.append(op)
    _save("file_operations.json", file_ops)

    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sid:
            s["last_activity_at"] = now
            s["updated_at"] = now
            break
    _save("sessions.json", sessions)

    latency_ms = int((time.monotonic() - t0) * 1000)
    return {"operation": op, "latency_ms": latency_ms}

