            if r.get("path") in (file_path, parent):
                if r.get("status") != "invalid":
                    r["status"] = "invalid"
                    r["updated_at"] = now
                    changed = True
        if changed:
            _save("fs_entries_cache.json", cache)

    if perr:
        op["status"] = "failed"
        op["error_message"] = perr["error"]["message"]
