def update_session_status(status, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0282000" if __import__("os").path.isdir("./environment_mix/0282000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.monotonic()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(status, str) or status not in ("active", "suspended", "closed"):
        return _err("VALIDATION_ERROR", "status must be one of 'active', 'suspended', 'closed'.", rule="status_enum")

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sess_rows = [s for s in sessions if isinstance(s, dict) and isinstance(s.get("id"), str) and s.get("status") in ("active", "suspended", "closed")]
    if not sess_rows:
        return _err("UNAUTHORIZED", "No session available.")

    sess_rows.sort(key=lambda s: (s.get("last_activity_at") or "", s.get("updated_at") or "", s.get("created_at") or "", s.get("id")), reverse=True)
    sess = None
    for st in ("active", "suspended", "closed"):
        for s in sess_rows:
            if s.get("status") == st:
                sess = s
                break
        if sess:
            break
    if not sess:
        sess = sess_rows[0]

    sid = sess.get("id")
    current = sess.get("status")

    if current == "closed":
        return _err("INVALID_TRANSITION", "Cannot modify a closed session.", session_id=sid, current_status=current)

    transitions = {
        "active": {"suspended", "closed"},
        "suspended": {"active", "closed"},
        "closed": set(),
    }

    if status != current and status not in transitions.get(current, set()):
        return _err("INVALID_TRANSITION", "Illegal session status transition.", session_id=sid, from_status=current, to_status=status)

    # Apply mutation and persist (idempotent if same)
    updated_session = None
    found = False
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sid:
            found = True
            if s.get("status") != status:
                s["status"] = status
            s["updated_at"] = now
            s["last_activity_at"] = now
            updated_session = dict(s)
            break

    if not found or updated_session is None:
        return _err("NOT_FOUND", "Session not found.", session_id=sid)

    _save("sessions.json", sessions)

    latency_ms = int((time.monotonic() - t0) * 1000)
    return {"session": updated_session, "latency_ms": latency_ms}

