def list_command_executions(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0282000" if __import__("os").path.isdir("./environment_mix/0282000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Resolve an accessible session (ambient auth). Prefer active, else suspended; never closed.
    sessions = _load("sessions.json")
    session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") == "active":
            session = s
            break
    if session is None:
        for s in sessions:
            if isinstance(s, dict) and s.get("status") == "suspended":
                session = s
                break
    if session is None:
        # No usable session => UNAUTHORIZED per contract (no combination can serve).
        # Also log this read attempt.
        execs = _load("command_executions.json")
        latency_ms = int((time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "No accessible session available for listing command executions.", latency_ms=latency_ms)

    # Validate params
    allowed_status = {"queued", "running", "succeeded", "failed", "timed_out", "cancelled"}
    if status is None:
        status = "succeeded"
    if not isinstance(status, str) or status not in allowed_status:
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=sorted(list(allowed_status)))
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "Invalid limit type; expected integer.")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor type; expected string or null.")

    # Load and filter
    executions = _load("command_executions.json")
    sid = session.get("id")
    filtered = []
    for r in executions:
        if not isinstance(r, dict):
            continue
        if r.get("session_id") != sid:
            continue
        if r.get("status") != status:
            continue
        filtered.append(r)

    # Sort by created_at DESC (fallback to id)
    def _ts(v):
        if not isinstance(v, str):
            return ""
        return v
    filtered.sort(key=lambda x: (_ts(x.get("created_at")), str(x.get("id"))), reverse=True)

    # Cursor: opaque string; we accept either exact id, or a hashed token "ce:<id>:<sha>"
    after_id = None
    if cursor:
        if cursor.startswith("ce:"):
            parts = cursor.split(":")
            if len(parts) >= 2:
                after_id = parts[1]
        else:
            after_id = cursor

    start_idx = 0
    if after_id is not None:
        for i, r in enumerate(filtered):
            if str(r.get("id")) == after_id:
                start_idx = i + 1
                break

    page = filtered[start_idx:start_idx + limit]
    has_more = start_idx + limit < len(filtered)

    next_cursor = None
    if has_more and page:
        last_id = str(page[-1].get("id"))
        # Create an opaque-ish cursor stable across calls.
        token = hashlib.sha256(last_id.encode("utf-8")).hexdigest()[:16]
        next_cursor = f"ce:{last_id}:{token}"

    # Update session last activity (read-only operation still counts as activity)
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == sid:
            sessions[i] = dict(s)
            sessions[i]["last_activity_at"] = now
            sessions[i]["updated_at"] = now
            break
    _save("sessions.json", sessions)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "object": "list",
        "data": page,
        "session_id": sid,
        "filter": {"status": status},
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": len(filtered)
        },
        "request": {
            "timestamp": now,
            "latency_ms": latency_ms
        }
    }

def cancel_command_execution(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0282000" if __import__("os").path.isdir("./environment_mix/0282000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.monotonic()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Invalid id; expected non-empty string.", rule="id_non_empty")

    sessions = _load("sessions.json")
    executions = _load("command_executions.json")
    if not isinstance(sessions, list):
        sessions = []
    if not isinstance(executions, list):
        executions = []

    # resolve current session (ambient auth)
    sess_rows = [s for s in sessions if isinstance(s, dict) and isinstance(s.get("id"), str)]
    sess_rows.sort(key=lambda s: (s.get("last_activity_at") or "", s.get("updated_at") or "", s.get("created_at") or "", s.get("id")), reverse=True)
    sess = None
    for st in ("active", "suspended", "closed"):
        for s in sess_rows:
            if s.get("status") == st:
                sess = s
                break
        if sess:
            break
    if not sess:
        return _err("UNAUTHORIZED", "No session available to cancel command execution.")

    sid = sess.get("id")
    if sess.get("status") == "closed":
        return _err("INVALID_TRANSITION", "Session is closed; operation rejected.", session_id=sid)
    if sess.get("status") == "suspended":
        return _err("INVALID_TRANSITION", "Session is suspended; mutating operations are not allowed.", session_id=sid)

    idx = None
    row = None
    for i, r in enumerate(executions):
        if isinstance(r, dict) and str(r.get("id")) == id:
            idx = i
            row = r
            break
    if row is None:
        return _err("NOT_FOUND", "Command execution not found.", id=id)
    if row.get("session_id") != sid:
        return _err("UNAUTHORIZED", "Not authorized to cancel this command execution.", id=id)

    terminal = {"succeeded", "failed", "timed_out", "cancelled"}
    cur = row.get("status")
    if cur in terminal:
        return _err("CONFLICT", "Command execution is already in a terminal state.", id=id, status=cur)

    allowed = {"queued", "running"}
    if cur not in allowed:
        return _err("INVALID_TRANSITION", "Illegal command execution status transition.", id=id, from_status=cur, to_status="cancelled")

    # transition to cancelled and set completion fields
    row["status"] = "cancelled"
    row["finished_at"] = now
    if row.get("started_at") and not row.get("duration_ms"):
        # best-effort duration computation if started_at parseable
        try:
            st = row.get("started_at")
            if isinstance(st, str) and st.endswith("Z"):
                started = datetime.datetime.fromisoformat(st[:-1])
                dur = int((now_dt - started).total_seconds() * 1000)
                if dur < 0:
                    dur = 0
                row["duration_ms"] = dur
        except Exception:
            # do not fail on duration calc
            pass
    elif not row.get("started_at"):
        row["duration_ms"] = 0 if row.get("duration_ms") is None else row.get("duration_ms")
    row["updated_at"] = now

    executions[idx] = row
    _save("command_executions.json", executions)

    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sid:
            s["last_activity_at"] = now
            s["updated_at"] = now
            break
    _save("sessions.json", sessions)

    latency_ms = int((time.monotonic() - t0) * 1000)
    return {"command_execution": row, "latency_ms": latency_ms}
